ee:message.ee:set-payload:
%dw 2.0
output application/json
---
if(isEmpty(payload))
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": ""
  },
  "messageServer": "Data not found",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.exception.NotFoundExcecption"
    }
  ]
}
else
payload[0] -'_id'

set-variable.value:
#[%dw 2.0
output application/json
---
{
  "aggregate": p('mongoDb-mdm.mayoristas.collection-order'),
  "pipeline": [
    {
      "\$match": {
        // Filtros dinámicos: Solo se agregan si el parámetro existe
        ( "Numero_Orden": vars.parameters.OrderNumber ) if (vars.parameters.OrderNumber != null),
        ( "Cliente_Tramite.Numero_Documento": vars.parameters.CustomerId ) if (vars.parameters.CustomerId != null),
        ( "Cliente_Tramite.Tipo_Documento": vars.parameters.CustomerIdType ) if (vars.parameters.CustomerIdType != null),

        // Filtros del objeto Agendamiento
        "Agendamiento.Agenda": true,

        // El rango de fechas también puede ser opcional
        ( "Agendamiento.Fecha_Agenda": {
          "\$gte": { "\$date": vars.parameters.StartDate },
          "\$lte": { "\$date": vars.parameters.EndDate }
        }) if (vars.parameters.StartDate != null and vars.parameters.EndDate != null)
      }
    },
    {
      "\$sort": { 
        "Agendamiento.Fecha_Agenda": -1 
      }
    },
    {
      "\$skip": vars.parameters.OffSet as Number default 0
    },
    {
      "\$limit": vars.parameters.Limit as Number default 10
    }
  ],
  "cursor": {}
}]
